        auto const& d0Value = EwaldConst::fourExpansion<5>(i);
        T const hdotx = simdFma(simdBroadcast<T>(h[0]), position[0],
            simdFma(simdBroadcast<T>(h[1]), position[1], simdBroadcast<T>(h[2]) * position[2]));
