        s4 = simdFma(s4, ar2, simdBroadcast<T>(6.61375661375661420e-05));
        s4 = simdFma(s4, ar2, simdBroadcast<T>(-4.38596491228070184e-04));
        s4 = simdFma(s4, ar2, simdBroadcast<T>(2.45098039215686271e-03));
