        x[7] = x[2] * x[2];     // 0 2 0 | 0 1 0 | 0 1 0
        x[6] = x[1] * x[3];     // 1 0 1 | 0 0 1 | 1 0 0
        x[5] = x[1] * x[2];     // 1 1 0 | 0 1 0 | 1 0 0
        x[4] = x[1] * x[1];     // 2 0 0 | 1 0 0 | 1 0 0
