        x[18] = x[8] * x[3];    // 0 1 2 | 0 0 1 | 0 1 1
        x[17] = x[8] * x[2];    // 0 2 1 | 0 1 0 | 0 1 1
        x[16] = x[7] * x[2];    // 0 3 0 | 0 1 0 | 0 2 0
        x[15] = x[6] * x[3];    // 1 0 2 | 0 0 1 | 1 0 1
