        x[13] = x[5] * x[2];    // 1 2 0 | 0 1 0 | 1 1 0
        x[12] = x[6] * x[1];    // 2 0 1 | 1 0 0 | 1 0 1
        x[11] = x[5] * x[1];    // 2 1 0 | 1 0 0 | 1 1 0
